<?php
require_once 'config.php'; require_once 'includes/auth_check.php';
$message=''; $error=''; $userId=(int)$_SESSION['user_id'];
if ($_SERVER['REQUEST_METHOD']==='POST') { try { require_csrf(); $current=$_POST['current_password']??''; $new=$_POST['new_password']??''; $confirm=$_POST['confirm_password']??''; $stmt=$conn->prepare('SELECT password FROM users WHERE id=?'); $stmt->bind_param('i',$userId); $stmt->execute(); $row=$stmt->get_result()->fetch_assoc(); $stmt->close(); if (!$row || !password_verify($current,$row['password'])) throw new RuntimeException('Current password is incorrect.'); if (strlen($new)<8 || !preg_match('/[A-Za-z]/',$new) || !preg_match('/\d/',$new)) throw new RuntimeException('New password must be at least 8 characters and include a letter and a number.'); if ($new!==$confirm) throw new RuntimeException('New passwords do not match.'); $hash=password_hash($new,PASSWORD_DEFAULT); $stmt=$conn->prepare('UPDATE users SET password=? WHERE id=?'); $stmt->bind_param('si',$hash,$userId); $stmt->execute(); $stmt->close(); audit_log($conn,'change_password','user',$userId,'Password changed successfully'); $message='Password changed successfully.'; } catch(Throwable $e){$error=$e->getMessage();} }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Change Password | Grievance Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"></head><body class="bg-light"><div class="d-flex min-vh-100"><?php include 'includes/sidebar.php'; ?><main class="flex-grow-1"><header class="bg-white border-bottom p-3"><h4 class="mb-0">Change Password</h4><small class="text-muted">Use a strong password that you do not reuse elsewhere.</small></header><div class="container p-4"><div class="card border-0 shadow-sm" style="max-width:620px"><div class="card-body p-4"><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="mb-3"><label class="form-label">Current password</label><input class="form-control" type="password" name="current_password" required></div><div class="mb-3"><label class="form-label">New password</label><input class="form-control" type="password" name="new_password" minlength="8" required></div><div class="mb-4"><label class="form-label">Confirm new password</label><input class="form-control" type="password" name="confirm_password" minlength="8" required></div><button class="btn btn-primary">Update password</button></form></div></div></div></main></div></body></html>
